create or replace function public.get_admin_payment_detail(p_reference text) returns table(reference text,event_name text,organization_name text,status text,gross_minor bigint,refunded_minor bigint,provider_fee_minor bigint,platform_fee_minor bigint,organizer_net_minor bigint,created_at timestamptz,confirmed_at timestamptz) language sql stable security definer set search_path='' as $$ select p.provider_reference,e.name,o.name,coalesce(l.status,p.status),p.total_amount_minor,coalesce(l.refunded_amount_minor,0),coalesce(l.provider_fee_minor,0),coalesce(l.platform_fee_minor,0),coalesce(l.organizer_net_minor,0),p.created_at,p.confirmed_at from public.payment_attempts p join public.organizations o on o.id=p.organization_id left join public.events e on e.id=p.event_id left join public.paid_vote_ledger l on l.reference=p.provider_reference where p.provider_reference=p_reference and exists(select 1 from public.platform_admins a where a.user_id=auth.uid() and a.is_active); $$;
revoke all on function public.get_admin_payment_detail(text) from public,anon; grant execute on function public.get_admin_payment_detail(text) to authenticated;
create or replace function public.get_admin_payment_webhooks(p_reference text) returns table(id text,kind text,resource text,processed_at timestamptz,created_at timestamptz) language sql stable security definer set search_path='' as $$ select j.id,j.kind,j.resource,j.processed_at,j.created_at from public.payment_jobs j where j.resource=p_reference and exists(select 1 from public.platform_admins a where a.user_id=auth.uid() and a.is_active) order by j.created_at desc; $$;
revoke all on function public.get_admin_payment_webhooks(text) from public,anon; grant execute on function public.get_admin_payment_webhooks(text) to authenticated;
